body{--hf:var(--site-font-heading);--hw:800;--on:var(--site-surface);--rad:18px;--bw:3px;--bc:var(--site-text);--shd:6px 6px 0 var(--site-text);--h1:66px;--h2:48px;}

.btn{border:3px solid var(--site-text);background:var(--site-primary);color:var(--on);font-weight:800;box-shadow:4px 4px 0 var(--site-text);transition:translate .15s,box-shadow .15s}
.btn:hover{translate:2px 2px;box-shadow:2px 2px 0 var(--site-text)}
.btn.alt{background:var(--site-surface);color:var(--site-text)}
.hl{display:inline-block;color:var(--site-primary);background:var(--site-surface);border:3px solid var(--site-text);padding:0 12px;rotate:1.5deg}
.kicker{background:var(--site-text);color:var(--site-background);padding:4px 16px;rotate:-2deg;font-weight:800}
.ph{background:radial-gradient(color-mix(in srgb,var(--site-primary) 22%,transparent) 2px,transparent 2.5px) 0 0/18px 18px,var(--site-surface);outline:3px solid var(--site-text);outline-offset:-3px}
.scene{border-radius:50%;background:var(--site-background);border:3px dashed var(--site-text);animation:wobble 4s ease-in-out infinite}

.shead{margin-bottom:56px}.shead.split{display:flex;align-items:end;justify-content:space-between;gap:24px;flex-wrap:wrap}.shead.split p{max-width:380px}.shead.center p{margin-top:12px}
.ghead{margin-bottom:52px}
.rhead{margin-bottom:56px}
.n1{position:sticky;top:0;z-index:20;background:color-mix(in srgb,var(--site-background) 92%,transparent);backdrop-filter:blur(10px);border-bottom:1px solid color-mix(in srgb,var(--site-text) 10%,transparent)}
.n1 .wrap{display:flex;align-items:center;gap:36px;height:84px}.n1 .links{margin-inline-start:auto}
.hv3{padding:72px 0 100px}.hv3 .wrap{display:grid;grid-template-columns:1.1fr .9fr;gap:60px;align-items:center}
.hv3 .plate{position:relative;rotate:2deg}.hv3 .tilt{height:460px}.hv3 .sp{position:absolute;top:-70px;inset-inline-start:-60px}
.a4{background:var(--site-primary);color:var(--on);padding:140px 0;clip-path:polygon(0 6%,100% 0,100% 94%,0 100%)}
.a4 .wrap{display:grid;grid-template-columns:1fr 1.3fr;gap:64px;align-items:center}.a4 h2{font-size:calc(var(--h2) * 1.2)}.a4 p{font-size:22px;line-height:1.95}
.s4 .svc{display:grid;grid-template-columns:repeat(var(--cols),minmax(0,1fr));gap:20px}
.s4 li{background:var(--site-surface);border-radius:var(--rad);border:var(--bw) solid var(--bc);padding:32px 28px 36px;transition:background .25s,color .25s}
.s4 li::before{content:"";display:block;width:48px;height:48px;border-radius:50%;border:8px solid var(--site-primary);margin-bottom:26px}
.s4 li:hover{background:var(--site-text);color:var(--site-background)}.s4 li:hover p{color:color-mix(in srgb,var(--site-background) 75%,transparent)}.s4 h3{font-size:26px;margin-bottom:10px}.s4 p{color:var(--site-muted)}
.g3{background:var(--site-surface)}.g3 .grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:28px}
.g3 figure{margin:0;padding:12px 12px 18px;background:var(--site-surface);border:var(--bw) solid var(--bc);box-shadow:var(--shd)}.g3 .ph{height:260px}
.g3 figure:nth-child(odd){rotate:-2deg}.g3 figure:nth-child(even){rotate:2deg;margin-top:30px}
.r3 .grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:32px}
.r3 blockquote{position:relative;padding:28px;background:var(--site-surface);border:var(--bw) solid var(--site-text);border-radius:22px;font-size:19px;font-weight:600}
.r3 blockquote::after{content:"";position:absolute;bottom:-14px;inset-inline-start:40px;width:24px;height:24px;background:var(--site-surface);border-inline-end:var(--bw) solid var(--site-text);border-bottom:var(--bw) solid var(--site-text);rotate:45deg}
.r3 figcaption{margin-top:26px;padding-inline-start:30px;font-family:var(--hf);color:var(--site-primary);font-weight:700}
.c3{padding:110px 0}.c3 .box{position:relative;overflow:hidden;background:var(--site-primary);color:var(--on);border-radius:calc(var(--rad) * 1.4);border:var(--bw) solid var(--bc);padding:90px 40px}
.c3 .box::before,.c3 .box::after{content:"";position:absolute;border-radius:50%;background:color-mix(in srgb,var(--on) 14%,transparent);animation:float 8s ease-in-out infinite}
.c3 .box::before{width:260px;height:260px;top:-80px;left:-60px}.c3 .box::after{width:160px;height:160px;bottom:-50px;right:80px;animation-delay:-3s}
.c3 h2,.c3 p,.c3 .btn{position:relative;z-index:1}.c3 p{font-size:21px;margin:16px auto 36px;max-width:580px}.c3 .btn.inv{background:var(--on);color:var(--site-primary)}
.f1{border-top:1px solid color-mix(in srgb,var(--site-text) 12%,transparent);padding:30px 0;color:var(--site-muted);font-size:15px}.f1 .wrap{display:flex;justify-content:space-between;gap:20px;flex-wrap:wrap}

@media (max-width:1100px){
  body{--h1:52px;--h2:40px}
  .links{display:none}
  .cl{grid-template-columns:1fr!important}
  .cl2{grid-template-columns:repeat(2,minmax(0,1fr))!important}
  .wrap{padding:0 28px}
}
@media (prefers-reduced-motion:reduce){
  *,*::before,*::after{animation:none!important;transition:none!important;scroll-behavior:auto!important}
}


/* barq: صور حقيقية مكان الـplaceholder، والرسمة 3D جوه مكانها، وكل قسم relative (الترتيب الحر في المحرر). */
